import sys
from collections import defaultdict

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    strings = []
    for _ in range(n):
        try:
            strings.append(next(iterator))
        except StopIteration:
            break

    if len(strings) != n:
        print(0)
        return

    if n == 1:
        s = strings[0]
        if s[0] == s[-1]:
            print(1)
        else:
            print(0)
        return

    in_degree = defaultdict(int)
    out_degree = defaultdict(int)

    for s in strings:
        first = s[0]
        last = s[-1]
        out_degree[first] += 1
        in_degree[last] += 1

    all_chars = set(out_degree.keys()) | set(in_degree.keys())

    for char in all_chars:
        if in_degree[char] != out_degree[char]:
            print(0)
            return

    adj = defaultdict(list)
    for s in strings:
        u = s[0]
        v = s[-1]
        adj[u].append(v)

    start_node = strings[0][0]
    visited_count = 0
    stack = [start_node]

    while stack:
        node = stack.pop()
        while adj[node]:
            next_node = adj[node].pop()
            stack.append(node)
            stack.append(next_node)
            break
        else:
            visited_count += 1

    if visited_count != n:
        print(0)
        return

    print(1)

if __name__ == "__main__":
    solve()
